        } 
        // 3. Blue Statuses (Renewals)
        else if (s.includes('Renewal') || s === 'Renewed') {
            return [__(s), "blue", "custom_contract_status,=," + s];
        } 
        // 4. Green Statuses (Approved, Issued)
        else if (['Issued', 'Internally Approved', 'CEO Approved', 'Team Lead Approved'].includes(s)) {
            return [__(s), "green", "custom_contract_status,=," + s];
        } 
