        else if (state === 'Objectives Approved' || state === 'Objectives Rejected') { s.s1 = 'completed'; s.s2 = 'completed'; s.s3 = 'active'; }
        else if (state === 'Pending Manager Review') { s.s1 = 'completed'; s.s2 = 'completed'; s.s3 = 'completed'; s.s4 = 'active'; }
        else if (state === 'Completed') { s.s1 = 'completed'; s.s2 = 'completed'; s.s3 = 'completed'; s.s4 = 'completed'; s.s5 = 'completed active'; }

