                .stepper-item.completed::after, .stepper-item.completed::before { border-bottom: 4px solid #1c9b4f; }
                .stepper-item.active::after { border-bottom: 4px solid #1c9b4f; }
                .step-counter { z-index: 5; display: flex; justify-content: center; align-items: center; width: 34px; height: 34px; border-radius: 50%; background: #e0e0e0; color: #fff; font-weight: bold; }
                .stepper-item.active .step-counter, .stepper-item.completed .step-counter { background-color: #1c9b4f; }
                .step-name { margin-top: 10px; font-size: 13px; font-weight: bold; color: #888; text-align: center; }
                .stepper-item.active .step-name, .stepper-item.completed .step-name { color: #1c9b4f; }
            </style>
