frappe.ui.form.on('Job Requisition', {
    // 1. AUTO-CALCULATE TOTAL CTC
    custom_gross_annual_salary: function(frm) { calculate_total_ctc(frm); },
    custom_medical_reimbursements_per_year: function(frm) { calculate_total_ctc(frm); },
    custom_communications_cost_per_year: function(frm) { calculate_total_ctc(frm); },
    custom_seat_cost: function(frm) { calculate_total_ctc(frm); },

    // 2. AUTO-STAMP DATES & VERIFY USER ON WORKFLOW ACTION
    before_workflow_action: function(frm) {
        let action = frm.selected_workflow_action;
        let current_state = frm.doc.workflow_state;
        let today = frappe.datetime.get_today();
        let logged_in_user = frappe.session.user;

        // Only run validation and stamping for Approvals and Finalizations
        if (action.includes('Approve') || action.includes('Finalize')) {
            
            if (current_state.includes('Pending Dept Manager')) {
                if (frm.doc.custom_department_manager !== logged_in_user) {
                    frappe.throw(__('Only the selected Department Manager can approve this step.'));
                }
                frm.set_value('custom_department_manager_date', today);
            } 
            else if (current_state.includes('Pending HR')) {
                if (frm.doc.custom_human_resources !== logged_in_user) {
                    frappe.throw(__('Only the selected HR Representative can approve this step.'));
                }
                frm.set_value('custom_hr_date', today);
            } 
            else if (current_state.includes('Pending Finance')) {
                if (frm.doc.custom_finance !== logged_in_user) {
                    frappe.throw(__('Only the selected Finance Representative can approve this step.'));
                }
                frm.set_value('custom_finance_date', today);
            } 
            else if (current_state.includes('Pending Director')) {
                if (frm.doc.custom_director !== logged_in_user) {
                    frappe.throw(__('Only the selected Director can finalize this step.'));
                }
                frm.set_value('custom_director_date', today);
            }
        }
    }
});

// Helper function for the CTC math
function calculate_total_ctc(frm) {
    let gross = flt(frm.doc.custom_gross_annual_salary);
    let med = flt(frm.doc.custom_medical_reimbursements_per_year);
    let comms = flt(frm.doc.custom_communications_cost_per_year);
    let seat = flt(frm.doc.custom_seat_cost);

    let total = gross + med + comms + seat;
    frm.set_value('custom_total_ctc', total);
}

