            if (!isHR) {
                // Allow if it's our custom green document link
                let isOurDocLink = $(e.target).closest('a').attr('target') === '_blank';
                
                if (!isOurDocLink) {
                    // Block everything else (Policy Name, row click, etc.)
                    e.stopPropagation();
                    e.preventDefault();
                    return false;
                }
            }
        });
