            try {
                fileName = decodeURIComponent(fileName);
            } catch(e) {}

            return `<a href="${value}" target="_blank" onclick="event.stopPropagation();" style="color: #15803d; font-weight: 500; font-size: 13px; text-decoration: none;">
                📄 ${fileName}
            </a>`;
        }
    }
};

