        frm.custom_old_lead = frm.doc.lead_approver_review || "";
        frm.custom_old_legal = frm.doc.legal_approver_review || "";
        frm.custom_old_finance = frm.doc.finance_approver_review || "";
        frm.custom_old_hr = frm.doc.hr_approver_review || "";
        frm.custom_old_ceo = frm.doc.ceo_approver_review || "";

        // 2. Force ONLY these specific review boxes to be exactly 1 line tall (~36px)
        let review_fields = [
            'lead_approver_review', 
            'legal_approver_review', 
            'finance_approver_review', 
            'hr_approver_review', 
            'ceo_approver_review'
        ];
        
        review_fields.forEach(field => {
            if (frm.fields_dict[field] && frm.fields_dict[field].$input) {
                frm.fields_dict[field].$input.css({
                    'height': '36px', 
                    'min-height': '36px'
                });
            }
        });
    },

    validate: function(frm) {
        let timestamp = " [Reviewed on: " + frappe.datetime.now_datetime() + "]";

        // 1. Check Lead Approver
        let current_lead = frm.doc.lead_approver_review || "";
        if (current_lead !== frm.custom_old_lead) {
            if (frappe.session.user !== frm.doc.lead_approver) {
                frappe.msgprint("You are not authorized! Only the assigned Lead Approver can write here.");
                frappe.validated = false; 
            } else if (frm.doc.workflow_state !== 'Pending Team Lead Approval') { 
                frappe.msgprint("You can only write or modify the Lead Review during the 'Pending Team Lead Approval' stage.");
                frappe.validated = false;
            } else if (!current_lead.includes("[Reviewed on:")) {
                frm.doc.lead_approver_review += timestamp; 
            }
        }
        
        // 2. Check Legal Approver
        let current_legal = frm.doc.legal_approver_review || "";
        if (current_legal !== frm.custom_old_legal) {
            if (frappe.session.user !== frm.doc.legal_approver) {
                frappe.msgprint("You are not authorized! Only the assigned Legal Approver can write here.");
                frappe.validated = false; 
            } else if (frm.doc.workflow_state !== 'Pending Level 2.1 Legal Approval') {
                frappe.msgprint("You can only write or modify the Legal Review during the 'Pending Level 2.1 Legal Approval' stage.");
                frappe.validated = false;
            } else if (!current_legal.includes("[Reviewed on:")) {
                frm.doc.legal_approver_review += timestamp;
            }
        }

        // 3. Check Finance Approver
        let current_finance = frm.doc.finance_approver_review || "";
        if (current_finance !== frm.custom_old_finance) {
            if (frappe.session.user !== frm.doc.finance_approver) {
                frappe.msgprint("You are not authorized! Only the assigned Finance Approver can write here.");
                frappe.validated = false; 
            } else if (frm.doc.workflow_state !== 'Pending Level 2.2 Finance Approval') {
                frappe.msgprint("You can only write or modify the Finance Review during the 'Pending Level 2.2 Finance Approval' stage.");
                frappe.validated = false;
            } else if (!current_finance.includes("[Reviewed on:")) {
                frm.doc.finance_approver_review += timestamp;
            }
        }

        // 4. Check HR Approver
        let current_hr = frm.doc.hr_approver_review || "";
        if (current_hr !== frm.custom_old_hr) {
            if (frappe.session.user !== frm.doc.hr_approver) {
                frappe.msgprint("You are not authorized! Only the assigned HR Approver can write here.");
                frappe.validated = false; 
            } else if (frm.doc.workflow_state !== 'Pending Level 2.3 HR Approval') {
                frappe.msgprint("You can only write or modify the HR Review during the 'Pending Level 2.3 HR Approval' stage.");
                frappe.validated = false;
            } else if (!current_hr.includes("[Reviewed on:")) {
                frm.doc.hr_approver_review += timestamp;
            }
        }

        // 5. Check CEO Approver
        let current_ceo = frm.doc.ceo_approver_review || "";
        if (current_ceo !== frm.custom_old_ceo) {
            if (frappe.session.user !== frm.doc.ceo_approver) {
                frappe.msgprint("You are not authorized! Only the assigned CEO Approver can write here.");
                frappe.validated = false; 
            } else if (frm.doc.workflow_state !== 'Pending CEO Approval') {
                frappe.msgprint("You can only write or modify the CEO Review during the 'Pending CEO Approval' stage.");
                frappe.validated = false;
            } else if (!current_ceo.includes("[Reviewed on:")) {
                frm.doc.ceo_approver_review += timestamp;
            }
        }
    },

    before_workflow_action: function(frm) {
        let action = frm.selected_workflow_action;
        
        // This catches ANY button that includes the word "Reject"
        if (action && action.includes('Reject')) { 
            let state = frm.doc.workflow_state;
            let msg = "You must provide a reason in your review box before rejecting this contract.";

            // frappe.throw() acts as a hard emergency brake and completely kills the process
            if (state === 'Pending Team Lead Approval' && !frm.doc.lead_approver_review) {
                frappe.throw(msg);
            }
            if (state === 'Pending Level 2.1 Legal Approval' && !frm.doc.legal_approver_review) {
                frappe.throw(msg);
            }
            if (state === 'Pending Level 2.2 Finance Approval' && !frm.doc.finance_approver_review) {
                frappe.throw(msg);
            }
            if (state === 'Pending Level 2.3 HR Approval' && !frm.doc.hr_approver_review) {
                frappe.throw(msg);
            }
            if (state === 'Pending CEO Approval' && !frm.doc.ceo_approver_review) {
                frappe.throw(msg);
            }
        }
    }
});

frappe.ui.form.on('Customer', {
    refresh: function(frm) {
        if (!frm.is_new() && !frm.doc.custom_customer_code) {
            frm.set_value('custom_customer_code', frm.doc.name);
            frm.save();
        }
    }
});
